import {bounds,transformedPoints,autoArrange,validateLayout,exportSVG,exportDXF,exportSTL,zipFiles,createDemoProject} from './geometry.js';
import {openCapture} from './capture.js';
import {esc,icon,openModal,closeModal,toast,download} from './ui.js';
import {uid,clone,validateProject,readLocal,writeLocal,blankProject} from './model.js';

const $=s=>document.querySelector(s);
const fmt=(v,d=1)=>Number(v).toLocaleString('cs-CZ',{maximumFractionDigits:d});
const slug=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'-').replace(/^-|-$/g,'').toLowerCase()||'suplik';
const paths=points=>points.map((p,i)=>`${i?'L':'M'}${p.x.toFixed(2)},${p.y.toFixed(2)}`).join(' ')+'Z';
const palette=['#acb998','#a4b9a9','#b4bd9e','#aebda1','#bdb7a1','#b3bda8'];
const storageKey='suplik-studio-projects-v1',libraryKey='suplik-studio-library-v1';
let projects=readLocal(storageKey,[]);
if(!Array.isArray(projects))projects=[];
projects=projects.flatMap(p=>{try{return[validateProject(p)]}catch{return[]}});
let project=projects.find(p=>p.id===readLocal('suplik-studio-current',''))||projects[0];
if(!project){project=validateProject({...createDemoProject(),id:uid()});projects=[project];}
let library=readLocal(libraryKey,null);
if(!Array.isArray(library))library=createDemoProject().tools.map(t=>({...clone(t),x:0,y:0,moduleId:null}));
library=library.flatMap(t=>{try{return[validateProject({...blankProject(),tools:[t]}).tools[0]];}catch{return[];}});
let selected=project.tools[0]?.id||null,selectedModule=null,inspectorTab='drawer',view='2d',zoom=1,snap=true,showGrid=true,showLabels=true,tipVisible=!readLocal('suplik-hide-tip',false);
let undoStack=[],redoStack=[],drag=null,storageFailed=false;
const tool=()=>project.tools.find(t=>t.id===selected);
const moduleFor=(t=tool())=>project.modules.find(m=>m.id===(t?.moduleId||selectedModule));
const errors=()=>validateLayout(project);
function remember(){undoStack.push(clone(project));if(undoStack.length>40)undoStack.shift();redoStack=[];}
function persist(){
  project.updatedAt=new Date().toISOString();const index=projects.findIndex(p=>p.id===project.id);if(index>=0)projects[index]=clone(project);else projects.push(clone(project));
  const ok=writeLocal(storageKey,projects)&&writeLocal('suplik-studio-current',project.id);
  if(!ok&&!storageFailed){storageFailed=true;toast('Úložiště prohlížeče je plné nebo vypnuté. Uložte projekt jako JSON.');}return ok;
}
function commit(fn,message){remember();fn();persist();render();if(message)toast(message);}
function arrange(message=true){const result=autoArrange(project);project.tools=result.tools;project.modules=result.modules;if(message)toast(result.unplaced.length?`${result.unplaced.length} nástrojů se nevešlo. Rozšiřte šuplík nebo uvolněte zamčené moduly.`:'Rozložení hotové. Zamčené moduly zůstaly na svém místě.');return result;}
function thumb(t){const b=bounds({...t,x:0,y:0,rotation:0});return `<svg viewBox="${-3} ${-3} ${b.width+6} ${b.height+6}" aria-hidden="true"><path d="${paths(transformedPoints({...t,x:0,y:0,rotation:0}))}" fill="${t.id===selected?'#c79c53':'#9fae90'}" stroke="none"/></svg>`;}
function input(label,value,key,{unit='mm',min=0,max=3000,step=1,scope='project',type='number'}={}){return `<label class="field"><span>${label}</span><div class="input-wrap"><input type="${type}" value="${esc(value)}" data-field="${key}" data-scope="${scope}" ${type==='number'?`min="${min}" max="${max}" step="${step}"`:''} aria-label="${label}">${unit?`<em>${unit}</em>`:''}</div></label>`;}
function drawerPanel(){return `<div class="panel-header"><h2 class="panel-title">${icon('ruler')} Rozměry šuplíku</h2><span>mm</span></div><div class="panel-body"><div class="fields-row">${input('Šířka',project.width,'width',{min:42})}${input('Hloubka',project.height,'height',{min:42})}</div><div class="fields-row">${input('Výška inzertu',project.insertHeight,'insertHeight',{min:3,max:100})}${input('Rastr modulů',project.grid,'grid',{min:10,max:100})}</div><div class="panel-rule"></div><div class="toggle-row"><span>Přichytit k rastru</span><button class="switch ${snap?'on':''}" data-action="snap" role="switch" aria-checked="${snap}" aria-label="Přichytit k rastru"></button></div><div class="fields-row">${input('Vůle kontury',project.clearance,'clearance',{min:0,max:5,step:.1})}${input('Tloušťka dna',project.base,'base',{min:1,max:20,step:.2})}</div>${input('Minimální stěna',project.wall,'wall',{min:1,max:15,step:.2})}<button class="btn btn-soft block-button" data-action="expand">${icon('expand')} Rozšířit sestavu</button><p class="muted-note">Rastr ${fmt(project.grid)} mm · samostatné moduly s plochým dnem. Každý můžete vytisknout zvlášť.</p></div>`;}
function selectedPanel(){const t=tool(),m=moduleFor();if(!t&&!m)return `<div class="panel-header"><h2 class="panel-title">Vlastnosti nástroje</h2></div><div class="empty-note">Vyberte nástroj v náhledu nebo v seznamu.</div>`;if(!t)return `<div class="panel-header"><h2 class="panel-title">Prázdný modul</h2><button class="icon-btn" data-action="drawer-tab" aria-label="Rozměry šuplíku">${icon('ruler')}</button></div><div class="panel-body"><span class="pill">${fmt(m.width)} × ${fmt(m.height)} mm</span><p class="muted-note">Výplňový modul · ${m.locked?'zamčená':'volná'} poloha</p><div class="selected-actions"><button class="btn btn-light" data-action="lock">${icon(m.locked?'unlock':'lock')}${m.locked?'Odemknout':'Zamknout'}</button><button class="btn btn-danger" data-action="delete">${icon('trash')}Smazat</button></div></div>`;
return `<div class="panel-header"><h2 class="panel-title">${icon('wrench')} Vybraný nástroj</h2><button class="icon-btn" data-action="drawer-tab" aria-label="Rozměry šuplíku">${icon('ruler')}</button></div><div class="panel-body">${input('Název',t.name,'name',{type:'text',unit:'',scope:'tool'})}<div class="fields-row">${input('Šířka kontury',Math.round(bounds(t).width*10)/10,'toolWidth',{scope:'tool',min:2,max:2000,step:.1})}${input('Hloubka kapsy',t.depth,'depth',{scope:'tool',min:.5,max:project.insertHeight-project.base,step:.5})}</div>${m?`<span class="pill">Modul ${fmt(m.width/project.grid,0)} × ${fmt(m.height/project.grid,0)} · ${fmt(m.width)} × ${fmt(m.height)} mm</span>`:'<div class="issue-box">Nástroj čeká na umístění.</div>'}<div class="selected-actions"><button class="btn btn-light" data-action="rotate">${icon('rotate')}Otočit 90°</button><button class="btn btn-light" data-action="lock">${icon(m?.locked?'unlock':'lock')}${m?.locked?'Odemknout':'Zamknout'}</button><button class="btn btn-light" data-action="duplicate">${icon('copy')}Kopie</button><button class="btn btn-danger" data-action="delete" aria-label="Smazat nástroj">${icon('trash')}</button></div><p class="muted-note">${m?.locked?'Zamčený modul automatické rozvržení nepřesune.':'Modul přesuňte tažením. Zamknutím zachováte polohu při dalším rozvržení.'}</p></div>`;}
function render(){
  const issues=errors(),unplaced=project.tools.filter(t=>!project.modules.some(m=>m.id===t.moduleId));
  const occupied=project.modules.reduce((s,m)=>s+m.width*m.height,0),usage=Math.min(100,Math.round(occupied/(project.width*project.height)*100));
  $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand" href="#" aria-label="Šuplík Studio" data-action="home"><span class="brand-mark"><i></i><i></i><i></i><i></i></span><span class="brand-name">šuplík<small>STUDIO</small></span></a><nav class="sidebar-nav" aria-label="Hlavní navigace"><button class="nav-item active" data-action="home">${icon('drawer')}<span>Můj šuplík</span></button><button class="nav-item" data-action="library">${icon('wrench')}<span>Knihovna nástrojů</span></button><button class="nav-item" data-action="projects">${icon('folder')}<span>Moje projekty</span></button></nav><div class="sidebar-separator"></div><div class="sidebar-label">AKTUÁLNÍ PROJEKT</div><button class="project-mini" data-action="projects"><div class="mini-icon">${icon('grid')}</div><div><strong>${esc(project.name)}</strong><span>${fmt(project.width)} × ${fmt(project.height)} mm</span></div></button><div class="sidebar-bottom"><button class="nav-item" data-action="help">${icon('help')}<span>Jak na to</span></button><div class="sidebar-separator" style="margin:18px 0"></div><div class="local-tag">${icon('shield')} Všechno zůstává u vás</div><p>Fotky zpracovává váš prohlížeč.<br>Bez cloudu. Bez předplatného.</p></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Dílna <span>/</span> <b>Organizér nářadí</b></div><div class="top-actions"><span class="save-state">${icon(storageFailed?'info':'check')} ${storageFailed?'Stáhněte zálohu':'Uloženo v zařízení'}</span><button class="btn btn-light" data-action="save-project">${icon('download')} Uložit projekt</button><span class="avatar" title="Lokální dílna">JD</span></div></header><div class="page"><div class="page-heading"><div><p class="eyebrow">MÍSTO PRO KAŽDÝ NÁSTROJ</p><div class="name-edit"><h1>${esc(project.name)}</h1><button class="icon-btn" data-action="rename" aria-label="Přejmenovat projekt">${icon('edit')}</button></div><p class="subtitle">Od fotky k pořádku. Přesně podle vaší dílny.</p></div><div class="heading-actions"><button class="btn btn-light" data-action="add-shape">${icon('plus')} Prázdný modul</button><button class="btn btn-primary" data-action="capture">${icon('camera')} <span>Přidat nástroj</span></button></div></div><div class="steps" aria-label="Postup"><button class="step done" data-action="capture"><span class="step-num">01</span>Vyfotit nástroj</button><span class="step-chevron">›</span><button class="step done" data-action="capture"><span class="step-num">02</span>Rozpoznat obrys</button><span class="step-chevron">›</span><span class="step active"><span class="step-num">03</span>Rozvrhnout</span><span class="step-chevron">›</span><button class="step" data-action="export"><span class="step-num">04</span>Vyrobit</button></div><div class="workbench"><div class="workspace-col"><section class="workspace" aria-label="Editor sestavy"><div class="workspace-header"><div class="workspace-header-title">${icon('drawer')} Náhled šuplíku <small>${fmt(project.width)} × ${fmt(project.height)} mm</small></div><div class="segmented" aria-label="Režim náhledu"><button data-action="2d" class="${view==='2d'?'active':''}" aria-pressed="${view==='2d'}">${icon('grid')}2D</button><button data-action="3d" class="${view==='3d'?'active':''}" aria-pressed="${view==='3d'}">${icon('cube')}3D</button></div></div><div class="board-toolbar"><div class="tool-group"><button class="icon-btn" data-action="undo" aria-label="Zpět (Ctrl+Z)" ${undoStack.length?'':'disabled'}>${icon('undo')}</button><button class="icon-btn" data-action="redo" aria-label="Znovu (Ctrl+Shift+Z)" ${redoStack.length?'':'disabled'}>${icon('redo')}</button><span class="toolbar-sep"></span><button class="icon-btn ${showGrid?'active':''}" data-action="grid" aria-label="Zobrazit rastr" aria-pressed="${showGrid}">${icon('grid')}</button><button class="tiny-button" data-action="labels" aria-pressed="${showLabels}">${icon('eye')} Popisky</button></div><button class="tiny-button" data-action="auto">${icon('spark')} Auto rozložení</button></div><div class="board-area" id="board-area"><svg class="board-svg" id="board-svg" role="img" aria-label="Rozložení modulů a nástrojů v šuplíku"></svg>${!project.modules.length?`<div class="board-empty">${icon('drawer')}<h3>Začněte jedním nástrojem</h3><p>Vyfoťte ho na A4 papíru nebo vložte z uložené knihovny.</p><button class="btn btn-primary" data-action="capture">${icon('camera')} Přidat nástroj</button></div>`:''}</div><div class="board-footer"><div class="legend"><span><i></i>Modul</span><span><i></i>Vybraný nástroj</span></div><div class="key-hint">${view==='2d'?'Tažením přesunete modul':'Prostorový náhled'} <kbd>R</kbd> otočit</div><div class="tool-group"><button class="icon-btn" data-action="zoom-out" aria-label="Oddálit">${icon('zoomOut')}</button><span>${Math.round(zoom*100)} %</span><button class="icon-btn" data-action="zoom-in" aria-label="Přiblížit">${icon('zoomIn')}</button><button class="icon-btn" data-action="fit" aria-label="Zobrazit vše">${icon('fit')}</button></div></div></section><div class="metrics"><div class="metric"><div class="metric-icon">${icon('wrench')}</div><div><strong>${project.tools.length} <small>nástrojů</small></strong><p>${unplaced.length?`${unplaced.length} čeká na umístění`:'Každý má svoje místo'}</p></div></div><div class="metric"><div class="metric-icon">${icon('grid')}</div><div><strong>${project.modules.length} <small>modulů</small></strong><p>${project.modules.filter(m=>m.locked).length} zamčených · rozšiřitelné</p></div></div><div class="metric"><div class="metric-icon">${icon('drawer')}</div><div><strong>${usage} <small>% plochy</small></strong><p>${Math.max(0,100-usage)} % na další nástroje</p></div></div></div>${issues.length?`<div class="issue-box" role="status">${issues.slice(0,3).map(i=>`<p>${esc(i.message)}</p>`).join('')}${issues.length>3?`<p>A dalších ${issues.length-3} upozornění.</p>`:''}<button class="section-link" data-action="auto">Přepočítat rozvržení</button></div>`:''}${tipVisible?`<div class="tip">${icon('lightbulb')}<div><strong>Vaše dílna poroste. Sestava taky.</strong> Zamkněte hotové moduly a přidejte další nástroje. Auto rozložení zachová jejich polohu.</div><button class="icon-btn" data-action="hide-tip" aria-label="Skrýt tip">${icon('close')}</button></div>`:''}</div><aside class="inspector" aria-label="Nastavení a nástroje"><section class="panel">${inspectorTab==='tool'?selectedPanel():drawerPanel()}</section><section class="panel"><div class="panel-header"><h2 class="panel-title">Nástroje v sestavě</h2><span>${project.tools.length.toString().padStart(2,'0')}</span></div><div class="tool-list">${project.tools.map(t=>`<button class="tool-row ${selected===t.id?'selected':''}" data-select="${esc(t.id)}" aria-pressed="${selected===t.id}"><span class="tool-thumb">${thumb(t)}</span><span><strong>${esc(t.name)}</strong><small>${fmt(bounds(t).width,0)} × ${fmt(bounds(t).height,0)} mm${!t.moduleId?' · neumístěno':''}</small></span>${icon(project.modules.find(m=>m.id===t.moduleId)?.locked?'lock':'chevron')}</button>`).join('')||'<div class="empty-note">Zatím žádné nástroje.</div>'}</div><button class="add-tool-row" data-action="capture">${icon('plus')} Přidat další nástroj</button></section><div class="export-card"><div class="ready">${icon(issues.length?'info':'check')} ${issues.length?'Zkontrolujte sestavu':'Sestava připravena'}</div><p>${issues.length?'Před výrobou opravte označené rozměry nebo překryvy.':'STL pro 3D tisk, SVG a DXF pro výřez. Vše v reálných milimetrech.'}</p><button class="btn btn-dark block-button" data-action="export">${icon('download')} Připravit export ${icon('arrow')}</button></div></aside></div><footer class="footer-line"><span>Navrženo v milimetrech. Vyrobeno pro vaši dílnu.</span><button data-action="help">Návod a inspirace</button><span class="app-version">STUDIO / 1.1</span></footer></div></main></div><nav class="mobile-nav" aria-label="Mobilní navigace"><button class="active" data-action="home">${icon('drawer')}Šuplík</button><button data-action="library">${icon('wrench')}Knihovna</button><button class="camera-nav" data-action="capture" aria-label="Vyfotit nástroj">${icon('camera')}</button><button data-action="projects">${icon('folder')}Projekty</button><button data-action="export">${icon('download')}Export</button></nav>`;
  renderBoard();
}

function renderBoard(){
  const svg=$('#board-svg');if(!svg)return;
  if(view==='3d'){render3D(svg);return;}
  const pad=34,w=project.width+pad*2,h=project.height+pad*2;
  svg.setAttribute('viewBox',`${-pad+(w-w/zoom)/2} ${-pad+(h-h/zoom)/2} ${w/zoom} ${h/zoom}`);
  const issues=errors(),bad=new Set(issues.flatMap(x=>x.ids));
  let html=`<defs><pattern id="module-grid" width="${project.grid}" height="${project.grid}" patternUnits="userSpaceOnUse"><path d="M ${project.grid} 0 L 0 0 0 ${project.grid}" fill="none" stroke="#dce4d2" stroke-width=".65"/></pattern><pattern id="empty-hatch" width="5" height="5" patternUnits="userSpaceOnUse"><path d="M0 5L5 0" stroke="#e4e9dc" stroke-width=".45"/></pattern><filter id="softshadow" x="-10%" y="-10%" width="125%" height="125%"><feDropShadow dx="0" dy="2" stdDeviation="2" flood-color="#5b6846" flood-opacity=".08"/></filter></defs><rect x="-2" y="-2" width="${project.width+4}" height="${project.height+4}" rx="5" fill="#eff2e9" stroke="#c5cfb9" stroke-width="1.1"/><rect x="0" y="0" width="${project.width}" height="${project.height}" rx="3" fill="${showGrid?'url(#module-grid)':'#f4f7ee'}"/>`;
  html+=`<g stroke="#a4af97" stroke-width=".6"><path d="M0 -17H${project.width} M0 -21v8 M${project.width} -21v8"/><path d="M-17 0V${project.height} M-21 0h8 M-21 ${project.height}h8"/></g><rect x="${project.width/2-29}" y="-24" width="58" height="14" fill="#fbfcf9"/><text x="${project.width/2}" y="-14" text-anchor="middle" fill="#93a083" font-size="8.5">${fmt(project.width)} mm</text><text transform="translate(-23 ${project.height/2}) rotate(-90)" text-anchor="middle" fill="#93a083" font-size="8.5">${fmt(project.height)} mm</text>`;
  for(const [i,m] of project.modules.entries()){
    const ts=project.tools.filter(t=>t.moduleId===m.id),sel=ts.some(t=>t.id===selected)||selectedModule===m.id,isBad=bad.has(m.id)||ts.some(t=>bad.has(t.id));
    html+=`<g class="module" data-module="${esc(m.id)}" tabindex="0" role="button" aria-label="${esc(m.name)}${m.locked?' — zamčený':''}"><rect x="${m.x+.9}" y="${m.y+.9}" width="${m.width-1.8}" height="${m.height-1.8}" rx="3" fill="${sel?'#fcf0d7':palette[i%palette.length]+'20'}" stroke="${isBad?'#cb7d60':sel?'#dab06b':'#becdac'}" stroke-width="${sel?1.4:.8}" filter="url(#softshadow)"/>`;
    if(!ts.length)html+=`<rect x="${m.x+5}" y="${m.y+5}" width="${m.width-10}" height="${m.height-10}" fill="url(#empty-hatch)" rx="2"/><text x="${m.x+m.width/2}" y="${m.y+m.height/2}" fill="#a2af92" text-anchor="middle" font-size="8">PRÁZDNÝ MODUL</text>`;
    for(const t of ts){const b=bounds(t);html+=`<path class="tool-outline" d="${paths(transformedPoints(t,project.clearance))}" fill="${sel?'#e4b96c40':'#a8b99855'}" stroke="${isBad?'#bd775e':sel?'#be9555':'#90a67c'}" stroke-width=".8"/><path d="${paths(transformedPoints(t))}" fill="${sel?'#c99c4d2b':'#b7c6a377'}" stroke="${sel?'#bd975c':'#99ac86'}" stroke-width=".55"/>`;
      // Small etched centre detail reinforces the contour without changing the manufacturing outline.
      if(b.height>80&&b.width<65)html+=`<path d="M${b.x+b.width/2} ${b.y+b.height*.58}v${b.height*.24}" stroke="${sel?'#d3ad70':'#a9b896'}" stroke-width="1.1" stroke-linecap="round" opacity=".55"/>`;
    }
    if(showLabels){const label=ts[0]?.name||m.name,max=Math.max(9,Math.floor(m.width/4.5));html+=`<rect x="${m.x+6}" y="${m.y+m.height-15}" width="${Math.min(m.width-12,label.length*3.7+10)}" height="10" rx="2" fill="${sel?'#fff6e6':'#f3f6ee'}" opacity=".88"/><text x="${m.x+10}" y="${m.y+m.height-7.5}" fill="${sel?'#ab8547':'#8c9b7a'}" font-size="6.3">${esc(label.length>max?label.slice(0,max-1)+'…':label)}</text>`;}
    if(m.locked)html+=`<g transform="translate(${m.x+m.width-13} ${m.y+5}) scale(.33)" color="#8b9b78">${icon('lock')}</g>`;
    html+='</g>';
  }
  if(!project.modules.length&&showGrid)html+=`<text x="${project.width/2}" y="${project.height-14}" text-anchor="middle" font-size="7" fill="#b2bca5">${Math.floor(project.width/project.grid)} × ${Math.floor(project.height/project.grid)} polí · ${fmt(project.grid)} mm</text>`;
  else if(project.modules.length&&showLabels){const unusedY=Math.max(...project.modules.map(m=>m.y+m.height));if(project.height-unusedY>36)html+=`<text x="${project.width/2}" y="${unusedY+(project.height-unusedY)/2}" text-anchor="middle" font-size="8" fill="#b0bca1" letter-spacing=".8">PROSTOR PRO DALŠÍ NÁPADY</text>`;}
  svg.innerHTML=html;
}
function render3D(svg){
  const pr=(x,y,z=0)=>({x:(x-y)*.866,y:(x+y)*.43-z});
  const corners=[pr(0,0),pr(project.width,0),pr(project.width,project.height),pr(0,project.height)];
  const minX=Math.min(...corners.map(p=>p.x))-30,maxX=Math.max(...corners.map(p=>p.x))+30,maxY=Math.max(...corners.map(p=>p.y))+30;
  const w=maxX-minX,h=maxY+65;svg.setAttribute('viewBox',`${minX+(w-w/zoom)/2} ${-60+(h-h/zoom)/2} ${w/zoom} ${h/zoom}`);
  const poly=(ps)=>ps.map(p=>`${p.x},${p.y}`).join(' ');
  let html=`<polygon points="${poly(corners)}" fill="#e8eddf" stroke="#bfcbb2" stroke-width="1"/>`;
  if(showGrid)for(let x=project.grid;x<project.width;x+=project.grid){const a=pr(x,0),b=pr(x,project.height);html+=`<path d="M${a.x} ${a.y}L${b.x} ${b.y}" stroke="#d6dfca" stroke-width=".6"/>`;}
  if(showGrid)for(let y=project.grid;y<project.height;y+=project.grid){const a=pr(0,y),b=pr(project.width,y);html+=`<path d="M${a.x} ${a.y}L${b.x} ${b.y}" stroke="#d6dfca" stroke-width=".6"/>`;}
  for(const m of [...project.modules].sort((a,b)=>(a.x+a.y)-(b.x+b.y))){
    const H=project.insertHeight,ts=project.tools.filter(t=>t.moduleId===m.id),sel=ts.some(t=>t.id===selected)||selectedModule===m.id;
    const xy=[{x:m.x+.5,y:m.y+.5},{x:m.x+m.width-.5,y:m.y+.5},{x:m.x+m.width-.5,y:m.y+m.height-.5},{x:m.x+.5,y:m.y+m.height-.5}];
    html+=`<g data-module="${esc(m.id)}" class="module" tabindex="0" role="button" aria-label="${esc(m.name)}">`;
    for(const [a,b] of [[1,2],[2,3]])html+=`<polygon points="${poly([pr(xy[a].x,xy[a].y),pr(xy[b].x,xy[b].y),pr(xy[b].x,xy[b].y,H),pr(xy[a].x,xy[a].y,H)])}" fill="${sel?'#c8a265':'#a8b796'}" stroke="${sel?'#af8d58':'#96a883'}" stroke-width=".6"/>`;
    const top=xy.map(p=>pr(p.x,p.y,H));
    const holes=ts.map(t=>transformedPoints(t,project.clearance));
    html+=`<path d="${paths(top)} ${holes.map(p=>paths(p.map(p=>pr(p.x,p.y,H)))).join(' ')}" fill="${sel?'#f4dfb7':'#dce6ce'}" fill-rule="evenodd" stroke="${sel?'#d3ae72':'#b4c59f'}" stroke-width=".7"/>`;
    for(const [i,p] of holes.entries()){
      const t=ts[i],floor=H-t.depth,lip=p.map(p=>pr(p.x,p.y,H)),bottom=p.map(p=>pr(p.x,p.y,floor));
      html+=`<path d="${paths(lip)}" fill="${sel?'#9a7e50':'#81936d'}"/>`;
      // Clip the recessed floor to the opening to represent its depth correctly.
      html+=`<defs><clipPath id="clip-${esc(t.id)}"><path d="${paths(lip)}"/></clipPath></defs><path d="${paths(bottom)}" fill="${sel?'#c7a36c':'#aebe98'}" clip-path="url(#clip-${esc(t.id)})"/><path d="${paths(lip)}" fill="none" stroke="${sel?'#b7975d':'#9aad85'}" stroke-width=".75"/>`;
    }
    html+='</g>';
  }
  const pos=pr(project.width/2,project.height+26);html+=`<text x="${pos.x}" y="${pos.y}" fill="#92a07f" text-anchor="middle" font-size="8">${fmt(project.width)} × ${fmt(project.height)} × ${fmt(project.insertHeight)} mm · prostorový náhled</text>`;
  svg.innerHTML=html;
}

function switchProject(p){persist();project=clone(p);selected=project.tools[0]?.id||null;selectedModule=null;inspectorTab='drawer';undoStack=[];redoStack=[];zoom=1;persist();closeModal();render();}
function addTools(tools){
  if(project.tools.length+tools.length>300)throw Error('V jednom projektu může být nejvýše 300 nástrojů. Založte další projekt.');
  if(project.insertHeight-project.base<.5)throw Error('Výška inzertu musí být alespoň o 0,5 mm větší než tloušťka dna.');
  for(const t of tools)validateProject({...blankProject(),tools:[{...t,depth:Math.min(t.depth||12,project.insertHeight-project.base)}]});
  commit(()=>{for(const t of tools){const item={...t,id:uid(),depth:Math.min(t.depth||12,project.insertHeight-project.base),locked:false,moduleId:null};project.tools.push(item);if(!library.some(l=>l.name===item.name&&JSON.stringify(l.points)===JSON.stringify(item.points)))library.push({...clone(item),x:0,y:0,moduleId:null});}writeLocal(libraryKey,library);selected=project.tools.at(-1)?.id;inspectorTab='tool';arrange(false);},`Přidáno ${tools.length} ${tools.length===1?'nástroj':'nástrojů'}. Kontury jsou také v knihovně.`);
}
function capture(){openCapture({onAdd:addTools,toast});}
function undo(){if(!undoStack.length)return;redoStack.push(clone(project));project=undoStack.pop();persist();render();}
function redo(){if(!redoStack.length)return;undoStack.push(clone(project));project=redoStack.pop();persist();render();}
function rename(){const m=openModal({title:'Pojmenujte svůj šuplík',subtitle:'Název vám pomůže rozlišit uložené projekty.',body:input('Název projektu',project.name,'projectName',{type:'text',unit:''}),footer:'<span></span><button class="btn btn-primary" data-confirm>Přejmenovat</button>'});m.el.querySelector('[data-confirm]').onclick=()=>{const name=m.el.querySelector('input').value.trim();if(!name)return toast('Zadejte název projektu.');commit(()=>project.name=name.slice(0,100));m.close();};}
function expand(){const m=openModal({title:'Dílna poroste. Sestava taky.',subtitle:'Stávající moduly se zamknou a zůstanou přesně na svém místě.',body:`<p class="help-intro">Přidejte prostor v rastru ${fmt(project.grid)} mm. Zamčené moduly se při příštím automatickém rozložení nepřesunou.</p><div class="fields-row">${input('Nová šířka',project.width+project.grid,'expandWidth',{min:project.width,step:project.grid})}${input('Nová hloubka',project.height,'expandHeight',{min:project.height,step:project.grid})}</div><div class="tip">${icon('lock')} Zamkne se ${project.modules.length} stávajících modulů. Nové nástroje se umístí do volného místa.</div>`,footer:'<span class="footnote">Polohu můžete později odemknout u každého nástroje.</span><button class="btn btn-primary" data-confirm>Rozšířit sestavu</button>'});m.el.querySelector('[data-confirm]').onclick=()=>{const w=Number(m.el.querySelector('[data-field=expandWidth]').value),h=Number(m.el.querySelector('[data-field=expandHeight]').value);if(!Number.isFinite(w)||!Number.isFinite(h)||w<project.width||h<project.height||w>3000||h>3000)return toast('Nové rozměry musí být větší nebo stejné, nejvýše 3000 mm.');commit(()=>{project.width=w;project.height=h;project.modules.forEach(m=>m.locked=true);project.tools.forEach(t=>{if(project.modules.some(m=>m.id===t.moduleId))t.locked=true;});},'Sestava rozšířena. Stávající moduly jsou zamčené.');m.close();};}
function addShape(){const m=openModal({title:'Přidat modul nebo jednoduchý tvar',subtitle:'Výplň volného místa, přihrádka nebo kapsa se známým rozměrem.',body:`<label class="field"><span>Typ</span><select id="shape-type"><option value="blank">Prázdný plný modul</option><option value="rect">Obdélníková kapsa</option><option value="circle">Kruhová kapsa</option></select></label>${input('Název','Nový modul','shapeName',{type:'text',unit:''})}<div class="fields-row">${input('Šířka / průměr',84,'shapeWidth',{min:5,max:2000})}${input('Hloubka',84,'shapeHeight',{min:5,max:2000})}</div>`,footer:'<span class="footnote">Modul se umístí do prvního volného místa v rastru.</span><button class="btn btn-primary" data-confirm>Přidat do sestavy</button>'});m.el.querySelector('[data-confirm]').onclick=()=>{const type=m.el.querySelector('#shape-type').value,name=m.el.querySelector('[data-field=shapeName]').value.trim()||'Nový modul',w=Number(m.el.querySelector('[data-field=shapeWidth]').value),h=Number(m.el.querySelector('[data-field=shapeHeight]').value);if(!(w>=5&&w<=2000&&h>=5&&h<=2000))return toast('Zadejte rozměry od 5 do 2000 mm.');if(type!=='blank'){const points=type==='rect'?[{x:0,y:0},{x:w,y:0},{x:w,y:h},{x:0,y:h}]:Array.from({length:64},(_,i)=>({x:w/2+Math.cos(i*Math.PI/32)*w/2,y:w/2+Math.sin(i*Math.PI/32)*w/2}));try{addTools([{name,points,depth:12,x:0,y:0,rotation:0}]);m.close();}catch(error){toast(error.message);}return;}
    if(project.modules.length>=400)return toast('V projektu může být nejvýše 400 modulů.');const width=Math.ceil(w/project.grid)*project.grid,height=Math.ceil(h/project.grid)*project.grid;let pos=null;
    for(let y=0;y+height<=project.height&&!pos;y+=project.grid)for(let x=0;x+width<=project.width;x+=project.grid)if(!project.modules.some(o=>x<o.x+o.width&&x+width>o.x&&y<o.y+o.height&&y+height>o.y)){pos={x,y};break;}
    if(!pos)return toast('Modul se nevejde. Zmenšete jej nebo rozšiřte sestavu.');
    commit(()=>{const item={id:uid(),name,x:pos.x,y:pos.y,width,height,locked:true};project.modules.push(item);selected=null;selectedModule=item.id;inspectorTab='tool';},'Prázdný modul přidán a zamčen.');m.close();};}

function openLibrary(){const m=openModal({title:'Vaše knihovna nástrojů',subtitle:'Jednou načtený obrys můžete použít v každém dalším šuplíku.',wide:true,body:`<div class="library-grid">${library.map((t,i)=>`<div class="library-item"><span class="tool-thumb">${thumb(t)}</span><div><strong>${esc(t.name)}</strong><p>${fmt(bounds(t).width)} × ${fmt(bounds(t).height)} mm</p></div><button class="btn btn-light" data-library-add="${i}" aria-label="Přidat ${esc(t.name)} do sestavy">${icon('plus')}</button><button class="icon-btn" data-library-remove="${i}" aria-label="Odstranit ${esc(t.name)} z knihovny">${icon('trash')}</button></div>`).join('')||'<p class="empty-note">Vyfoťte první nástroj. Kontury se sem uloží automaticky.</p>'}</div>`,footer:`<span class="footnote">Knihovna je uložená v tomto prohlížeči.</span><button class="btn btn-primary" data-capture>${icon('camera')}Vyfotit nástroj</button>`});m.el.onclick=e=>{const add=e.target.closest('[data-library-add]'),remove=e.target.closest('[data-library-remove]');if(add){try{addTools([clone(library[Number(add.dataset.libraryAdd)])]);m.close();}catch(error){toast(error.message);}}if(remove){library.splice(Number(remove.dataset.libraryRemove),1);writeLocal(libraryKey,library);openLibrary();}if(e.target.closest('[data-capture]'))capture();};}
function openProjects(){persist();const m=openModal({title:'Moje projekty',subtitle:'Projekty se automaticky ukládají v tomto zařízení. Pro přenos si stáhněte JSON.',body:`<button class="btn btn-primary" data-new>${icon('plus')}Nový prázdný šuplík</button><button class="btn btn-light" data-import>${icon('upload')}Otevřít JSON</button>${projects.map(p=>`<div class="project-card"><div><h3>${esc(p.name)}</h3><p>${fmt(p.width)} × ${fmt(p.height)} mm · ${p.tools.length} nástrojů · ${p.modules.length} modulů${p.id===project.id?' · otevřený':''}</p></div><button class="btn btn-light" data-open="${esc(p.id)}">Otevřít</button>${p.id!==project.id?`<button class="icon-btn" data-remove-project="${esc(p.id)}" aria-label="Smazat projekt ${esc(p.name)}">${icon('trash')}</button>`:''}</div>`).join('')}`,footer:'<span class="footnote">Smazání dat prohlížeče odstraní místní projekty. JSON je vaše přenosná záloha.</span><button class="btn btn-light" data-demo>Ukázková sestava</button>'});m.el.onclick=e=>{if(e.target.closest('[data-new]'))switchProject(blankProject());if(e.target.closest('[data-import]'))$('#project-file').click();if(e.target.closest('[data-demo]'))switchProject(validateProject({...createDemoProject(),id:uid()}));const op=e.target.closest('[data-open]'),rm=e.target.closest('[data-remove-project]');if(op)switchProject(projects.find(p=>p.id===op.dataset.open));if(rm){projects=projects.filter(p=>p.id!==rm.dataset.removeProject);writeLocal(storageKey,projects);openProjects();}};}
function help(){openModal({title:'Z fotky do šuplíku',subtitle:'Čtyři kroky. Žádný CAD. Vše přímo ve vašem zařízení.',wide:true,body:`<div class="help-grid"><div class="help-card"><h3>01 / Vyfoťte nástroj</h3><p>Položte nástroje na bílou A4, odděleně od sebe. Celý papír musí být vidět. Fotografujte co nejvíc kolmo a v rozptýleném světle bez tvrdého stínu. Můžete použít i pravítko.</p></div><div class="help-card"><h3>02 / Obrys připravíme automaticky</h3><p>Aplikace najde A4 a narovná perspektivu. Lokální rozpoznávání oddělí předměty od pozadí a zpřesní obrys podle skutečných hran. Kontrast, odstranění šumu a vyhlazení zvolí samo. U pravítka označíte jen dvě známé značky pro měřítko.</p></div><div class="help-card"><h3>03 / Rozvrhněte sestavu</h3><p>Zadejte vnitřní rozměr šuplíku. Auto rozložení zkouší otočení a umístí obdélníkové moduly do rastru. Je to praktická heuristika, nemusí najít nejúspornější možné řešení. Vytištěné moduly zamkněte a přidávejte další kolem nich.</p></div><div class="help-card"><h3>04 / Exportujte a vyrobte</h3><p>STL obsahuje plné moduly s kapsami a plochým dnem. SVG/DXF jsou obrysy pro pěnu nebo CNC. Rastr 42 mm umožňuje sestavu rozšiřovat; nejde o plný profil Gridfinity s patkami. Nejdřív ověřte rozměr známého nástroje a vytiskněte zkušební modul.</p></div></div><h3 style="margin-top:27px">Alternativy, ze kterých vychází návrh</h3><p class="help-intro">Průzkum vlastností na oficiálních webech. Vlastní implementace; kód těchto aplikací se nepřebírá.</p><div class="help-grid"><div class="help-card"><h3>Outline App</h3><a href="https://github.com/georgslazdans/outline-app" target="_blank" rel="noopener noreferrer">Open source editor kontur ↗</a><p>Inspirace: kalibrace fotografie a převod obrysů do výrobních rozměrů.</p></div><div class="help-card"><h3>Tracefinity</h3><a href="https://github.com/tracefinity/tracefinity" target="_blank" rel="noopener noreferrer">Vlastní hostování a knihovna ↗</a><p>Inspirace: opakované použití nástrojů a projekty sestav.</p></div><div class="help-card"><h3>Binforge</h3><a href="https://binforge.app/" target="_blank" rel="noopener noreferrer">Plánování modulů v šuplíku ↗</a><p>Inspirace: jednoduchá práce s rozměry, rastr a samostatné exporty.</p></div><div class="help-card"><h3>TracetoForge</h3><a href="https://tracetoforge.com/" target="_blank" rel="noopener noreferrer">Fotografie → vlastní vložka ↗</a><p>Inspirace: kontrola měřítka, vůle a rozložení více nástrojů.</p></div></div><div class="tip" style="margin-top:20px">${icon('shield')} Fotografie se nikam neodesílají. Detekce kombinuje lokální model U²-Net a hrany v původní fotce. Pokud snímek nedává dost jistoty, vyžádá novou fotku. U zcela neviditelné hrany nelze skutečný tvar spolehlivě dopočítat.</div><p class="muted-note" style="margin-top:15px">Na mobilu: přidejte stránku na plochu přes nabídku prohlížeče. Po prvním načtení může editor díky uloženým souborům pracovat i offline. Projekty mezi zařízeními přenesete přes JSON.</p>`,footer:'<span class="footnote">Šuplík Studio 1.1 · vlastní editor bez účtu a předplatného.</span><button class="btn btn-dark" data-modal-close-extra>Rozumím, jdeme tvořit</button>'}).el.querySelector('[data-modal-close-extra]').onclick=closeModal;}

let exportFormat='stl',exportScope='all';
function openExport(){
  const t=tool(),m=moduleFor(),selectedId=m?.id||null;
  if(exportScope==='selected'&&!selectedId)exportScope='all';
  const fmtInfo={stl:['STL','3D tisk · kapsy a dno'],svg:['SVG','Pěna · laser · 1:1'],dxf:['DXF','CAD · CNC · mm'],json:['JSON','Projekt · přenos a záloha']};
  const entries=exportScope==='selected'?project.modules.filter(m=>m.id===selectedId):project.modules;
  const issues=exportScope==='selected'?validateLayout({...project,modules:entries,tools:project.tools.filter(t=>t.moduleId===selectedId)}):errors();
  const modal=openModal({title:'Z návrhu do vaší dílny',subtitle:'Vyberte formát a stáhněte soubory v reálném měřítku.',body:`<div class="format-grid">${Object.entries(fmtInfo).map(([key,[title,desc]])=>`<button class="format ${exportFormat===key?'active':''}" data-format="${key}"><strong>${title}</strong><span>${desc}</span></button>`).join('')}</div>${exportFormat!=='json'?`<label class="field"><span>Co exportovat</span><select id="export-scope"><option value="all" ${exportScope==='all'?'selected':''}>Celou sestavu${exportFormat==='stl'?' — ZIP se samostatnými STL moduly':''}</option><option value="selected" ${exportScope==='selected'?'selected':''} ${selectedId?'':'disabled'}>Vybraný modul${m?' · '+esc(m.name):''}</option></select></label>`:''}<div class="export-preview">${icon(exportFormat==='json'?'folder':exportFormat==='stl'?'cube':'file')}<div><strong>${esc(project.name)}</strong><small>${exportFormat==='json'?'Všechny kontury, rozměry, moduly a zamčené pozice':`${entries.length} modulů · ${exportScope==='selected'?fmt(m?.width)+' × '+fmt(m?.height):fmt(project.width)+' × '+fmt(project.height)} mm · vůle ${fmt(project.clearance)} mm`}</small></div></div>${issues.length&&exportFormat!=='json'?`<div class="issue-box">${issues.slice(0,3).map(i=>`<p>${esc(i.message)}</p>`).join('')}<p>Opravte sestavu před výrobním exportem. JSON lze uložit kdykoli.</p></div>`:''}${exportFormat==='stl'?`<div class="fields-row">${input('Tisková plocha · šířka',220,'bedWidth',{min:50,max:2000})}${input('Tisková plocha · hloubka',220,'bedHeight',{min:50,max:2000})}</div><div id="bed-warnings"></div><p class="muted-note">Každý STL je samostatný uzavřený modul. Výška ${fmt(project.insertHeight)} mm, dno nejméně ${fmt(project.base)} mm, spára mezi moduly 0,5 mm. Moduly mají ploché dno.</p>`:exportFormat==='svg'||exportFormat==='dxf'?'<p class="muted-note">Kontury kapes zahrnují nastavenou vůli. Černá / MODULES = vnější obrys modulu, červená / POCKETS = kapsa. SVG má rozměry v mm; při tisku vypněte přizpůsobení stránce.</p>':'<p class="muted-note">JSON přeneste do jiného zařízení a otevřete jej přes Moje projekty → Otevřít JSON. Fotografie nejsou součástí projektu; přesné načtené kontury ano.</p>'}<div class="tip" style="margin-top:17px">${icon('ruler')} Před výrobou ověřte rozměr a vyzkoušejte jeden modul. Perspektiva, odlesky a stín mohou obrys zkreslit.</div>`,footer:`<span class="footnote">${exportFormat==='stl'?'ZIP obsahuje očíslované STL soubory a přehled sestavy.':'Soubory se generují přímo ve vašem prohlížeči.'}</span><button class="btn btn-primary" data-do-export ${exportFormat!=='json'&&(issues.length||!entries.length)?'disabled':''}>${icon('download')}Stáhnout ${exportFormat==='stl'&&exportScope==='all'?'ZIP':exportFormat.toUpperCase()}</button>`});
  modal.el.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{exportFormat=b.dataset.format;openExport();});
  modal.el.querySelector('#export-scope')?.addEventListener('change',e=>{exportScope=e.target.value;openExport();});
  const bedWarnings=()=>{const bw=Number(modal.el.querySelector('[data-field=bedWidth]')?.value),bh=Number(modal.el.querySelector('[data-field=bedHeight]')?.value);const big=entries.filter(m=>!((m.width<=bw+.5&&m.height<=bh+.5)||(m.width<=bh+.5&&m.height<=bw+.5)));const el=modal.el.querySelector('#bed-warnings');if(el)el.innerHTML=big.length?`<div class="issue-box">${big.length} modulů přesahuje zadanou tiskovou plochu. Zvětšete plochu, upravte konturu nebo modul rozdělte ve sliceru.</div>`:'';};
  modal.el.querySelectorAll('[data-field^=bed]').forEach(i=>i.oninput=bedWarnings);bedWarnings();
  modal.el.querySelector('[data-do-export]').onclick=async e=>{
    const button=e.currentTarget;button.disabled=true;button.innerHTML='<span class="spinner"></span> Připravuji…';
    await new Promise(r=>requestAnimationFrame(()=>setTimeout(r,30)));
    try{
      const name=slug(project.name),options={moduleId:exportScope==='selected'?selectedId:null};
      if(exportFormat==='json')saveJSON();
      else if(exportFormat==='svg')download(name+'.svg',exportSVG(project,options),'image/svg+xml');
      else if(exportFormat==='dxf')download(name+'.dxf',exportDXF(project,options),'application/dxf');
      else if(exportScope==='selected')download(slug(m.name)+'.stl',exportSTL(project,options),'model/stl');
      else{
        const files=entries.map((m,i)=>({name:`${String(i+1).padStart(2,'0')}-${slug(m.name)}.stl`,data:exportSTL(project,{moduleId:m.id})}));
        files.push({name:'sestava.svg',data:exportSVG(project)},{name:'projekt.json',data:JSON.stringify({schemaVersion:1,app:'Suplik Studio',project},null,2)},{name:'CTETE-ME.txt',data:`Šuplík Studio\n${project.name}\nRozměry: ${project.width} × ${project.height} mm\nRastr: ${project.grid} mm; výška ${project.insertHeight} mm; vůle ${project.clearance} mm\n\nSamostatné moduly s plochým dnem. Všechny STL jsou v milimetrech.\nNejprve vytiskněte zkušební modul a ověřte vůli.\nSestava.svg ukazuje umístění modulů v šuplíku.\n\n${entries.map((m,i)=>`${i+1}. ${m.name}: ${m.width-.5} × ${m.height-.5} mm, poloha ${m.x},${m.y} mm${m.locked?' (zamčeno)':''}`).join('\n')}`});
        download(name+'-moduly.zip',zipFiles(files),'application/zip');
      }
      modal.close();toast('Soubor je připravený ve stažených souborech.');
    }catch(error){toast(error.message);button.disabled=false;button.innerHTML=icon('download')+' Zkusit znovu';}
  };
}
function saveJSON(){download(slug(project.name)+'.json',JSON.stringify({schemaVersion:1,app:'Suplik Studio',project},null,2),'application/json');}


const actions={
 home:()=>{closeModal();window.scrollTo({top:0,behavior:'smooth'});},capture,library:openLibrary,projects:openProjects,help,rename,expand,'add-shape':addShape,export:openExport,
 'save-project':()=>{persist();saveJSON();toast('Projekt uložen jako přenosný JSON.');},
 'drawer-tab':()=>{inspectorTab='drawer';render();},
 'edit-contour':capture,
 auto:()=>commit(()=>arrange()),
 undo,redo,
 snap:()=>{snap=!snap;render();},grid:()=>{showGrid=!showGrid;render();},labels:()=>{showLabels=!showLabels;render();},
 '2d':()=>{view='2d';zoom=1;render();},'3d':()=>{view='3d';zoom=1;render();},
 'zoom-in':()=>{zoom=Math.min(3,zoom+.25);render();},'zoom-out':()=>{zoom=Math.max(.5,zoom-.25);render();},fit:()=>{zoom=1;render();},
 'hide-tip':()=>{tipVisible=false;writeLocal('suplik-hide-tip',true);render();},
 rotate:()=>{const t=tool(),m=moduleFor();if(!t)return;if(m?.locked)return toast('Nejprve odemkněte polohu modulu.');commit(()=>{const b=bounds(t);t.rotation=(t.rotation+90)%360;const next=bounds(t);t.x=b.x+(b.width-next.width)/2;t.y=b.y+(b.height-next.height)/2;},'Nástroj otočen. Pokud přesahuje modul, spusťte Auto rozložení.');},
 lock:()=>{const m=moduleFor();if(!m)return;commit(()=>{m.locked=!m.locked;project.tools.filter(t=>t.moduleId===m.id).forEach(t=>t.locked=m.locked);},m.locked?'Poloha modulu je odemčená.':'Poloha modulu je zamčená.');},
 duplicate:()=>{const t=tool();if(t)addTools([{...clone(t),name:t.name+' · kopie'}]);},
 delete:()=>{const t=tool(),m=moduleFor();if(!t&&!m)return;commit(()=>{if(t){project.tools=project.tools.filter(x=>x.id!==t.id);project.modules=project.modules.filter(x=>x.id!==t.moduleId||project.tools.some(o=>o.moduleId===x.id));selected=project.tools[0]?.id||null;}else project.modules=project.modules.filter(x=>x.id!==m.id);selectedModule=null;},'Odstraněno ze sestavy. Akci můžete vrátit tlačítkem Zpět.');}
};
$('#app').addEventListener('click',e=>{const sel=e.target.closest('[data-select]');if(sel){selected=sel.dataset.select;selectedModule=null;inspectorTab='tool';render();return;}const a=e.target.closest('[data-action]');if(a){e.preventDefault();try{actions[a.dataset.action]?.();}catch(error){toast(error.message);}}});
$('#app').addEventListener('change',e=>{
  const el=e.target.closest('[data-field]');if(!el)return;const field=el.dataset.field,scope=el.dataset.scope;let value=el.type==='number'?Number(el.value):el.value.trim();
  if(el.type==='number'&&(!el.value||!Number.isFinite(value)||value<Number(el.min)||value>Number(el.max))){toast(`Zadejte hodnotu od ${el.min} do ${el.max}.`);render();return;}
    if(scope==='tool'){
    const t=tool();if(!t)return;
    if(field==='name'&&!value){render();return;}
    if(field==='toolWidth'){const ratio=value/bounds(t).width;if(t.points.some(p=>p.x*ratio>3000||p.y*ratio>3000)){toast('Kontura nesmí v žádném směru přesáhnout 3000 mm.');render();return;}}if(field==='toolWidth'&&moduleFor()?.locked){toast('Pro změnu rozměru nejdřív odemkněte modul.');render();return;}
    commit(()=>{if(field==='toolWidth'){const ratio=value/bounds(t).width;t.points=t.points.map(p=>({x:p.x*ratio,y:p.y*ratio}));}else t[field]=typeof value==='string'?value.slice(0,100):value;});
  }else commit(()=>project[field]=value);
});
$('#app').addEventListener('pointerdown',e=>{
  const group=e.target.closest('[data-module]'),svg=$('#board-svg');if(!group||!svg)return;
  const m=project.modules.find(m=>m.id===group.dataset.module);if(!m)return;
  const t=project.tools.find(t=>t.moduleId===m.id);selected=t?.id||null;selectedModule=t?null:m.id;inspectorTab='tool';
  if(view==='3d'||m.locked){render();if(m.locked)toast('Poloha modulu je zamčená. Odemkněte ji ve vlastnostech.');return;}
  e.preventDefault();const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const p=point.matrixTransform(svg.getScreenCTM().inverse());
  drag={pointer:e.pointerId,id:m.id,start:p,x:m.x,y:m.y,snapshot:clone(project),moved:false};svg.setPointerCapture(e.pointerId);renderBoard();
});
$('#app').addEventListener('pointermove',e=>{
  if(!drag)return;const svg=$('#board-svg'),p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform(svg.getScreenCTM().inverse());const m=project.modules.find(m=>m.id===drag.id);if(!m)return;
  const dx=q.x-drag.start.x,dy=q.y-drag.start.y;if(Math.hypot(dx,dy)<2&&!drag.moved)return;drag.moved=true;
  let x=drag.x+dx,y=drag.y+dy;if(snap){x=Math.round(x/project.grid)*project.grid;y=Math.round(y/project.grid)*project.grid;}x=Math.max(0,Math.min(project.width-m.width,x));y=Math.max(0,Math.min(project.height-m.height,y));
  const sx=x-m.x,sy=y-m.y;m.x=x;m.y=y;project.tools.filter(t=>t.moduleId===m.id).forEach(t=>{t.x+=sx;t.y+=sy;});renderBoard();
});
function endDrag(){if(!drag)return;if(drag.moved){const invalid=errors().some(i=>i.ids.includes(drag.id)&&i.type==='overlap');if(invalid){project=drag.snapshot;toast('Tady už je jiný modul. Zkuste volné místo.');}else{undoStack.push(drag.snapshot);redoStack=[];persist();}}drag=null;render();}
$('#app').addEventListener('pointerup',endDrag);$('#app').addEventListener('pointercancel',()=>{if(drag){project=drag.snapshot;drag=null;render();}});
$('#app').addEventListener('keydown',e=>{const group=e.target.closest('[data-module]');if(group&&(e.key==='Enter'||e.key===' ')){e.preventDefault();const m=project.modules.find(m=>m.id===group.dataset.module),t=project.tools.find(t=>t.moduleId===m.id);selected=t?.id||null;selectedModule=t?null:m.id;inspectorTab='tool';render();}});
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||$('#modal-root').children.length)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}else if(e.key.toLowerCase()==='r')actions.rotate();else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();actions.delete();}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();actions['save-project']();}});
$('#project-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>12*1024*1024)return toast('Projekt je příliš velký. Maximum je 12 MB.');try{const data=JSON.parse(await file.text());if(data.schemaVersion&&data.schemaVersion!==1)throw Error('Tato verze projektu zatím není podporovaná.');const imported=validateProject(data);imported.id=uid();switchProject(imported);toast('Projekt otevřen. Původní projekty zůstaly uložené.');}catch(error){toast('Projekt nelze otevřít: '+error.message);}});
persist();render();
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
